// Message timestamps are generated by the server, but the client's
// clock may disagree with the server's. We track that difference so
// that deadlines computed from message timestamps -- for editing,
// moving, and deleting messages -- match the ones the server will
// actually enforce.
let clock_offset_seconds = 0;

export function update_server_time_offset(server_timestamp: number): void {
    if (typeof server_timestamp === "number" && !Number.isNaN(server_timestamp)) {
        clock_offset_seconds = server_timestamp - Date.now() / 1000;
    }
}

export function get_server_time(): number {
    return Date.now() / 1000 + clock_offset_seconds;
}

export const now = get_server_time;

export function get_server_time_offset(): number {
    return clock_offset_seconds;
}

export function clear_for_testing(): void {
    clock_offset_seconds = 0;
}
